package com.example.notification_service.messaging;import com.example.notification_service.event.ApplicationEvent;import com.example.notification_service.service.NotificationProcessor;import io.micrometer.core.instrument.*;import org.slf4j.*;import org.springframework.amqp.AmqpRejectAndDontRequeueException;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.stereotype.Component;import tools.jackson.databind.json.JsonMapper;
@Component public class ApplicationEventListener{private static final Logger log=LoggerFactory.getLogger(ApplicationEventListener.class);private final JsonMapper json;private final NotificationProcessor processor;private final Counter dlq;public ApplicationEventListener(JsonMapper j,NotificationProcessor p,MeterRegistry meter){json=j;processor=p;dlq=meter.counter("notification.events.permanent_failure");}@RabbitListener(queues="${notification.messaging.queue}")public void receive(byte[] payload){ApplicationEvent event;try{event=json.readValue(payload,ApplicationEvent.class);if(event.eventVersion()!=1)throw new IllegalArgumentException();}catch(Exception e){dlq.increment();log.warn("notification_invalid_event errorType={}",e.getClass().getSimpleName());throw new AmqpRejectAndDontRequeueException("Invalid event contract",e);}try{processor.process(event);}catch(IllegalArgumentException e){dlq.increment();log.warn("notification_permanent_failure eventId={} applicationId={}",event.eventId(),event.data()==null?null:event.data().applicationId());throw new AmqpRejectAndDontRequeueException("Permanent notification failure",e);}}}
